import React, { useEffect, useState } from 'react';
import { BrowserRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { api } from './api';
import AuthPage from './pages/AuthPage';
import './App.css';

const Store = () => {
  const [products, setProducts] = useState([]);
  const [user, setUser] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({ title: '', category: '', description: '', price: '', stock: '' });
  const [editId, setEditId] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    // 1. Всегда загружаем товары (они доступны всем)
    refresh();

    // 2. Если есть токен, пробуем узнать, кто вошел
    if (localStorage.getItem('accessToken')) {
      api.getMe()
        .then(userData => setUser(userData))
        .catch(() => {
          // Если токен невалидный, просто сбрасываем его, но не выкидываем со страницы
          localStorage.clear();
          setUser(null);
        });
    }
  }, []);

  const refresh = () => api.getProducts().then(setProducts);

  const handleSave = async (e) => {
    e.preventDefault();
    if (editId) await api.updateProduct(editId, formData);
    else await api.createProduct(formData);
    close();
    refresh();
  };

  const close = () => { setShowModal(false); setEditId(null); setFormData({title:'', category:'', description:'', price:'', stock:''}); };
  const onEdit = (p) => { setEditId(p.id); setFormData(p); setShowModal(true); };
  const onDelete = async (id) => { if (window.confirm("Удалить?")) { await api.deleteProduct(id); refresh(); } };

  const handleLogout = () => {
    localStorage.clear();
    setUser(null); // Просто сбрасываем юзера, остаемся на странице магазина
  };

  return (
    <div className="store">
      <header className="header">
        <div className="container header-flex" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          
          {/* ЛЕВАЯ ЧАСТЬ: Логотип и Авторизация */}
          <div className="logo" style={{ display: 'flex', alignItems: 'center', gap: '30px' }}>
            <div>
              <h1>Nail Store</h1>
              <p>Professional beauty supplies</p>
            </div>
            
            {/* Если не вошли -> Кнопка "Войти", если вошли -> Имя и "Выйти" */}
            {!user ? (
              <button className="btn-add" onClick={() => navigate('/login')} style={{ padding: '8px 16px', fontSize: '14px' }}>
                Войти в систему
              </button>
            ) : (
              <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                <span style={{ fontWeight: '600', color: '#d4418e' }}>Привет, {user.username}!</span>
                <button className="btn-add" onClick={handleLogout} style={{ background: '#9ca3af', padding: '8px 16px', fontSize: '14px' }}>
                  Выйти
                </button>
              </div>
            )}
          </div>

          {/* ПРАВАЯ ЧАСТЬ: Добавление товара (только для авторизованных) */}
          {user && (
            <div>
              <button className="btn-add" onClick={() => setShowModal(true)}>+ Добавить товар</button>
            </div>
          )}
        </div>
      </header>

      {/* Модальное окно (работает только если user существует, так как кнопка скрыта) */}
      {showModal && (
        <div className="modal">
          <div className="modal-box">
            <h2>{editId ? "Редактировать" : "Новый товар"}</h2>
            <form onSubmit={handleSave}>
              <input placeholder="Название" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} required />
              <input placeholder="Категория" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} />
              <input placeholder="Цена" type="number" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} required />
              <input placeholder="Склад" type="number" value={formData.stock || ''} onChange={e => setFormData({...formData, stock: e.target.value})} />
              <textarea placeholder="Описание" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
              <div className="form-btns">
                <button type="submit" className="btn-save">Сохранить</button>
                <button type="button" className="btn-cancel" onClick={close}>Отмена</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Сетка товаров */}
      <div className="grid container">
        {products.map(p => (
          <div key={p.id} className="card">
            <div className="card-top">
              <span className="tag">{p.category || 'Товар'}</span>
              
              {/* Кнопки Ред./Удал. только для авторизованных */}
              {user && (
                <div className="actions">
                  <button className="act-btn edit" onClick={() => onEdit(p)}>✎</button>
                  <button className="act-btn del" onClick={() => onDelete(p.id)}>×</button>
                </div>
              )}
            </div>
            
            <h3>{p.title}</h3>
            <p className="desc">{p.description}</p>
            <div className="info">
              <span className="price">{p.price} ₽</span>
              <span className="stock">В наличии: {p.stock || 0}</span>
            </div>
            <button className="btn-cart">В корзину</button>
          </div>
        ))}
      </div>
    </div>
  );
};

// --- Роутер ---
function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/login" element={<AuthPage />} />
        <Route path="/" element={<Store />} />
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
